const data = $input.first().json;
const jobs = Array.isArray(data) ? data.slice(1) : [];
const today = new Date().toISOString().split('T')[0];

return jobs
  .filter(j => j && j.id && j.position)
  .map(j => ({
    json: {
      job_title: j.position || '',
      company: j.company || '',
      job_url: j.url || `https://remoteok.com/l/${j.slug || j.id}`,
      source: 'Remote OK',
      location_text: j.location || 'Worldwide',
      salary: (j.salary_min && j.salary_max) ? `$${j.salary_min}–$${j.salary_max}/yr` : (j.salary || ''),
      description: `${j.description || ''} Tags: ${(j.tags || []).join(', ')}`,
      posted_date: j.date || new Date().toISOString(),
      tags: (j.tags || []).join(', '),
      date_found: today
    }
