      source: 'Dynamite Jobs',
      location_text: 'Remote',
      salary: '',
      description: Array.isArray(item.description) ? item.description[0] : (item.description || ''),
      posted_date: Array.isArray(item.pubDate) ? item.pubDate[0] : (item.pubDate || new Date().toISOString()),
      tags: Array.isArray(item.category) ? item.category.join(', ') : (item.category || ''),
      date_found: today
    }
  };
