const data = $input.first().json;
const today = new Date().toISOString().split('T')[0];
// Wellfound may return JSON jobs array or HTML — handle both
let jobs = [];
if (data && Array.isArray(data.jobs)) {
  jobs = data.jobs;
} else if (data && Array.isArray(data.startups)) {
  for (const startup of data.startups) {
    for (const job of (startup.jobs || [])) {
      jobs.push({ ...job, company: startup.name });
    }
  }
}
if (jobs.length === 0) return [];

return jobs.map(j => ({
  json: {
    job_title: j.title || j.role || '',
    company: j.company || j.startup_name || '',
    job_url: j.url || j.job_url || `https://wellfound.com/jobs/${j.id || ''}`,
    source: 'Wellfound',
    location_text: j.locationNames?.join(', ') || j.remote ? 'Remote' : 'Unknown',
    salary: j.salary || j.compensation || '',
    description: j.description || j.summary || '',
    posted_date: j.createdAt || j.posted_at || new Date().toISOString(),
    tags: (j.skills || j.tags || []).join(', '),
    date_found: today
  }
}));

const data = $input.first().json;
const today = new Date().toISOString().split('T')[0];
let jobs = [];
if (Array.isArray(data)) {
  jobs = data;
} else if (data && Array.isArray(data.jobs)) {
  jobs = data.jobs;
}
if (jobs.length === 0) return [];

return jobs.map(j => ({
  json: {
    job_title: j.title || j.role || '',
    company: j.company?.name || j.startup?.name || '',
    job_url: j.url || `https://www.workatastartup.com/jobs/${j.id}`,
    source: 'YC Work at Startup',
    location_text: j.remote_ok ? 'Remote' : (j.locations?.join(', ') || 'Unknown'),
    salary: j.salary_range || '',
    description: j.description || j.body || '',
    posted_date: j.created_at || j.updated_at || new Date().toISOString(),
    tags: (j.tags || j.skills || []).join(', '),
    date_found: today
  }
}));

const data = $input.first().json;
const today = new Date().toISOString().split('T')[0];
const edges = data?.data?.jobs?.edges || [];
if (edges.length === 0) return [];

return edges.map(edge => {
  const j = edge.node || {};
  return {
    json: {
      job_title: j.title || '',
      company: j.company?.name || '',
      job_url: j.slug ? `https://app.otta.com/jobs/${j.slug}` : '',
      source: 'Otta',
      location_text: (j.locations || []).join(', ') || 'Remote',
      salary: j.salary || '',
      description: j.description || '',
      posted_date: new Date().toISOString(),
      tags: '',
      date_found: today
    }
  };
});

// Fetch existing URLs and keys from the Google Sheets node
const existingItems = $('Get Existing Job URLs').all();
const existingUrls = new Set(existingItems.map(i => i.json.job_url).filter(Boolean));
const existingKeys = new Set(
  existingItems
    .map(i => i.json.company && i.json.job_title ? `${i.json.company}||${i.json.job_title}`.toLowerCase() : null)
    .filter(Boolean)
);

const seenUrls = new Set();
const seenKeys = new Set();
const results = [];

for (const item of $input.all()) {
  const job = item.json;
  if (!job.job_url || !job.job_title) continue;

  const url = job.job_url.trim();
  const key = `${job.company || ''}||${job.job_title}`.toLowerCase();

  // Skip if already in sheets or already seen in this batch
  if (existingUrls.has(url) || seenUrls.has(url)) continue;
  if (job.company && existingKeys.has(key)) continue;
  if (job.company && seenKeys.has(key)) continue;

  // Generate stable job_id
  const hash = url.split('').reduce((a, c) => (a * 31 + c.charCodeAt(0)) | 0, 0);
  job.job_id = `${job.source.replace(/\s+/g, '-').toLowerCase()}-${Math.abs(hash)}`;

  seenUrls.add(url);
  if (job.company) seenKeys.add(key);
  results.push({ json: job });
}

return results;

const REJECT_PATTERNS = [
  /\bus[\s\-]?only\b/i,
  /united\s+states\s+only/i,
  /\bcanada[\s\-]?only\b/i,
  /\buk[\s\-]?only\b/i,
  /united\s+kingdom\s+only/i,
  /\beu[\s\-]?only\b/i,
  /\beurope[\s\-]?only\b/i,
  /european\s+union\s+only/i,
  /\baustralia[\s\-]?only\b/i,
  /must\s+be\s+based\s+in\b(?!.*taiwan)/i,
  /must\s+live\s+in\b(?!.*taiwan)/i,
  /must\s+be\s+authorized\s+to\s+work\s+in/i,
  /must\s+be\s+located\s+in\b(?!.*taiwan)/i,
  /must\s+reside\s+in\b(?!.*taiwan)/i,
  /local\s+work\s+permit\s+required/i,
  /\bhybrid\b/i,
  /\bon-?site\b/i,
  /office\s+required/i,
  /remote\s+within\s+(the\s+)?(us|uk|eu|canada|australia|united\s+states)/i,
  /fixed\s+us\s+hours/i,
  /fixed\s+eu\s+hours/i,
  /requires\s+us\s+citizenship/i,
  /us\s+citizens?\s+only/i,
  /authorized\s+to\s+work\s+in\s+the\s+us/i,
  /work\s+authorization\s+(in|for)\s+the\s+us/i,
  /must\s+be\s+a\s+us\s+(resident|citizen)/i,
  /restricted\s+to\s+(us|uk|eu|canada|australia)/i
];

const results = [];

for (const item of $input.all()) {
  const job = item.json;
  const text = `${job.job_title || ''} ${job.location_text || ''} ${job.description || ''} ${job.tags || ''}`.toLowerCase();

  let rejected = false;
  let reject_reason = '';

  for (const pattern of REJECT_PATTERNS) {
    if (pattern.test(text)) {
      rejected = true;
      reject_reason = `Hard filter: matched ${pattern}`;
      break;
    }
  }

  results.push({
    json: {
      ...job,
      _filter_result: rejected ? 'reject' : 'pass',
      _reject_reason: reject_reason
    }
  });
}

return results;

// Merge AI response back with the original job data
const jobItem = $('Batch Process Jobs').first();
const job = jobItem ? jobItem.json : {};

const aiResponse = $input.first().json;
let aiData = { taiwan_eligible: 'unclear', reason: 'Parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };

try {
  const content = aiResponse?.content?.[0]?.text || aiResponse?.choices?.[0]?.message?.content || '';
  // Strip markdown if present
  const jsonStr = content.replace(/```json?/g, '').replace(/```/g, '').trim();
  aiData = JSON.parse(jsonStr);
} catch (e) {
  // keep defaults
}

// SCORING SYSTEM (0–100)
let score = 0;
const desc = `${job.description || ''} ${job.location_text || ''} ${job.tags || ''}`.toLowerCase();

// --- Taiwan eligibility (40 pts max) ---
if (aiData.taiwan_eligible === 'yes' && aiData.location_risk === 'low') {
  score += 40;
} else if (aiData.taiwan_eligible === 'yes') {
  score += 35;
} else if (/worldwide|work from anywhere|global remote|anywhere|apac/i.test(desc)) {
  score += 40;
} else if (/contractor|deel|remote\.com|oyster|eor|b2b/i.test(desc)) {
  score += 35;
} else if (aiData.taiwan_eligible === 'unclear' && aiData.location_risk !== 'high') {
  score += 20;
} else {
  score += 0;
}

// --- Async fit (25 pts max) ---
if (/\basync\b|asynchronous/i.test(desc)) {
  score += 25;
} else if (/flexible hours|flexible schedule/i.test(desc)) {
  score += 20;
} else if (/distributed team/i.test(desc)) {
  score += 15;
} else if (/remote.?first|fully remote/i.test(desc)) {
  score += 10;
}

// --- Role fit (25 pts max) ---
const title = (job.job_title || '').toLowerCase();
if (/data (analyst|scientist|engineer)|bi analyst|business intelligence|growth analyst|marketing analyst|performance marketing|ai (marketing|automation|workflow)|martech|automation specialist|data science/i.test(title)) {
  score += 25;
} else if (/analyst|data|marketing|automation|growth|intelligence|ai |machine learning|creative strategist/i.test(title)) {
  score += 15;
}

// --- Salary fit (10–25 pts) ---
const salaryText = job.salary || '';
const salaryMatch = salaryText.match(/[\$£€]?([\d,]+)/);
if (salaryMatch) {
  const amount = parseInt(salaryMatch[1].replace(/,/g, ''));
  if (amount >= 5000) {
    score += 25;
  } else if (amount >= 3000) {
    score += 15;
  } else if (amount > 0) {
    score += 10;
  }
} else if (salaryText.length > 0) {
  score += 10;
}

// --- Async level label ---
let async_level = 'unknown';
if (/\basync\b|asynchronous/i.test(desc)) async_level = 'high';
else if (/flexible hours|flexible schedule|distributed/i.test(desc)) async_level = 'medium';
else if (/remote.?first|fully remote/i.test(desc)) async_level = 'low';

// --- Role category ---
let role_category = 'Other';
if (/data scientist|machine learning|ml/i.test(title)) role_category = 'Data Science';
else if (/data analyst|bi analyst|business intelligence/i.test(title)) role_category = 'Data Analytics';
else if (/marketing analyst|growth analyst|performance marketing/i.test(title)) role_category = 'Marketing Analytics';
else if (/ai (marketing|automation|workflow)|automation specialist/i.test(title)) role_category = 'AI Automation';
else if (/martech/i.test(title)) role_category = 'MarTech';
else if (/data/i.test(title)) role_category = 'Data';
else if (/marketing/i.test(title)) role_category = 'Marketing';

// --- Why good fit ---
const whyFit = [];
if (score >= 40 && /worldwide|work from anywhere|global|apac/i.test(desc)) whyFit.push('Global remote confirmed');
if (/async|asynchronous/i.test(desc)) whyFit.push('Async-first culture');
if (/contractor|deel|oyster|eor/i.test(desc)) whyFit.push('Contractor-friendly');
if (/data|analyst|scientist/i.test(title)) whyFit.push('Strong role fit for Jerry');
if (aiData.timezone_risk === 'low') whyFit.push('Taiwan timezone safe');

return [{
  json: {
    ...job,
    taiwan_eligible: aiData.taiwan_eligible,
    taiwan_reason: aiData.reason,
    location_risk: aiData.location_risk,
    timezone_risk: aiData.timezone_risk,
    contractor_possible: aiData.contractor_possible,
    ai_decision: aiData.decision,
    async_level,
    role_category,
    score,
    why_good_fit: whyFit.join('; ') || 'Passed all filters',
    application_status: 'Not applied',
    notes: ''
  }
}];

const jobItem = $('Score >= 85?').first();
const job = jobItem ? jobItem.json : {};

const aiResponse = $input.first().json;
const coverLetter = aiResponse?.content?.[0]?.text || 'Cover letter generation failed.';

return [{
  json: {
    ...job,
    cover_letter: coverLetter,
    cover_letter_length: coverLetter.split(' ').length
  }
}];

// Collect all jobs processed during this run
let filteredJobs = [];
let hardRejected = [];
let lowScoreRejected = [];

try { filteredJobs = $('Write Filtered Jobs').all().map(i => i.json); } catch(e) {}
try { hardRejected = $('Write Hard Rejected').all().map(i => i.json); } catch(e) {}
try { lowScoreRejected = $('Write Rejected (Low Score)').all().map(i => i.json); } catch(e) {}

const today = new Date().toLocaleDateString('en-US', { timeZone: 'Asia/Taipei', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

// Sort by score descending
const sorted = [...filteredJobs].sort((a, b) => (b.score || 0) - (a.score || 0));
const topJobs = sorted.slice(0, 10);
const alertJobs = sorted.filter(j => j.score >= 85);
const manualCheck = sorted.filter(j => j.taiwan_eligible === 'unclear' && j.score >= 70);

// Count rejection reasons
const usOnly = [...hardRejected, ...lowScoreRejected].filter(j => /us.?only|united states/i.test(j.reason || '')).length;
const euOnly = [...hardRejected, ...lowScoreRejected].filter(j => /eu.?only|europe/i.test(j.reason || '')).length;
const hybridCount = [...hardRejected, ...lowScoreRejected].filter(j => /hybrid/i.test(j.reason || '')).length;
const tzRisk = lowScoreRejected.filter(j => /timezone/i.test(j.reason || '') || j.timezone_risk === 'high').length;

let html = `<div style="font-family: Arial, sans-serif; max-width: 700px; margin: 0 auto;">`;
html += `<h1 style="color: #1a1a2e; border-bottom: 3px solid #16213e; padding-bottom: 10px;">🇹🇼 Daily Taiwan Eligible Async Remote Jobs</h1>`;
html += `<p style="color: #666;">${today} · ${filteredJobs.length} qualified · ${hardRejected.length + lowScoreRejected.length} rejected</p>`;

if (alertJobs.length > 0) {
  html += `<div style="background: #fff3cd; border: 2px solid #ffc107; padding: 15px; border-radius: 8px; margin: 20px 0;">`;
  html += `<h2 style="color: #856404; margin: 0 0 10px;">⚡ INSTANT ALERT — ${alertJobs.length} job${alertJobs.length > 1 ? 's' : ''} scoring 85+</h2>`;
  for (const j of alertJobs) {
    html += `<p><strong><a href="${j.job_url}">${j.job_title}</a></strong> @ ${j.company} — Score: ${j.score}</p>`;
  }
  html += `</div>`;
}

html += `<h2 style="color: #16213e;">Top Jobs Today</h2>`;

for (let i = 0; i < topJobs.length; i++) {
  const j = topJobs[i];
  const scoreColor = j.score >= 85 ? '#28a745' : j.score >= 70 ? '#17a2b8' : '#6c757d';
  html += `<div style="border: 1px solid #dee2e6; border-left: 5px solid ${scoreColor}; padding: 15px; margin: 15px 0; border-radius: 4px;">`;
  html += `<h3 style="margin: 0 0 8px;">${i + 1}. <a href="${j.job_url}" style="color: #1a1a2e; text-decoration: none;">${j.job_title}</a></h3>`;
  html += `<table style="font-size: 14px; color: #333; border-collapse: collapse; width: 100%;">`;
  html += `<tr><td style="padding: 3px 8px 3px 0; width: 130px; color: #666;">Company:</td><td><strong>${j.company}</strong></td></tr>`;
  html += `<tr><td style="padding: 3px 8px 3px 0; color: #666;">Score:</td><td><span style="background: ${scoreColor}; color: white; padding: 2px 8px; border-radius: 12px; font-size: 13px;">${j.score}/100</span></td></tr>`;
  html += `<tr><td style="padding: 3px 8px 3px 0; color: #666;">Taiwan eligible:</td><td>${j.taiwan_eligible === 'yes' ? '✅ Yes' : j.taiwan_eligible === 'unclear' ? '🟡 Unclear' : '❌ No'}</td></tr>`;
  html += `<tr><td style="padding: 3px 8px 3px 0; color: #666;">Reason:</td><td>${j.taiwan_reason || '—'}</td></tr>`;
  html += `<tr><td style="padding: 3px 8px 3px 0; color: #666;">Async level:</td><td>${j.async_level || '—'}</td></tr>`;
  html += `<tr><td style="padding: 3px 8px 3px 0; color: #666;">Timezone risk:</td><td>${j.timezone_risk || '—'}</td></tr>`;
  html += `<tr><td style="padding: 3px 8px 3px 0; color: #666;">Salary:</td><td>${j.salary || 'Not listed'}</td></tr>`;
  html += `<tr><td style="padding: 3px 8px 3px 0; color: #666;">Why it fits Jerry:</td><td>${j.why_good_fit || '—'}</td></tr>`;
  html += `</table>`;
  html += `<a href="${j.job_url}" style="display: inline-block; margin-top: 10px; background: #16213e; color: white; padding: 8px 16px; border-radius: 4px; text-decoration: none; font-size: 13px;">Apply →</a>`;
  html += `</div>`;
}

if (manualCheck.length > 0) {
  html += `<h2 style="color: #856404;">🔍 Manual Check Required</h2>`;
  html += `<p style="color: #666; font-size: 14px;">Taiwan eligibility unclear but score is high — review these yourself:</p>`;
  for (const j of manualCheck) {
    html += `<div style="background: #fff8e1; border: 1px solid #ffe082; padding: 10px; margin: 8px 0; border-radius: 4px;">`;
    html += `<strong><a href="${j.job_url}">${j.job_title}</a></strong> @ ${j.company}`;
    html += ` | Score: ${j.score} | Location risk: ${j.location_risk} | ${j.taiwan_reason}`;
    html += `</div>`;
  }
}

html += `<h2 style="color: #16213e;">Rejection Summary</h2>`;
html += `<ul style="color: #555; font-size: 14px;">`;
html += `<li>🇺🇸 Rejected — US only: <strong>${usOnly}</strong></li>`;
html += `<li>🇪🇺 Rejected — EU only: <strong>${euOnly}</strong></li>`;
html += `<li>🏢 Rejected — Hybrid/onsite: <strong>${hybridCount}</strong></li>`;
html += `<li>⏰ Rejected — Timezone risk: <strong>${tzRisk}</strong></li>`;
html += `<li>📊 Total rejected: <strong>${hardRejected.length + lowScoreRejected.length}</strong></li>`;
html += `</ul>`;

html += `<hr style="border: none; border-top: 1px solid #dee2e6; margin: 20px 0;">`;
html += `<p style="color: #aaa; font-size: 12px;">Generated by Taiwan Eligible Async Remote Job Hunter · n8n · ${new Date().toISOString()}</p>`;
html += `</div>`;

return [{
  json: {
    digest_html: html,
    total_qualified: filteredJobs.length,
    total_rejected: hardRejected.length + lowScoreRejected.length,
    alert_jobs: alertJobs.length,
    manual_check_jobs: manualCheck.length,
    subject: `🇹🇼 Taiwan Jobs: ${filteredJobs.length} qualified${alertJobs.length > 0 ? ' ⚡ ' + alertJobs.length + ' high-score' : ''} — ${today}`
  }
}];
